    "title": "Luke 14: Lowest Seat at the Feast & Great Banquet for the Outcast",
    "subtitle": "Advising guests to choose humble seats and telling hosts to invite the poor, crippled, lame, and blind—before picturing God’s wide supper hall rushing travelers in off highways and hedges.",
    "summaryHook": "Advising guests to choose humble seats and telling hosts to invite the poor, crippled, lame, and blind—before picturing God’s wide supper hall rushing travelers in off highways and hedges.",
    "bigPictureText": "Turns social climbing upside down at every meal until empty banquet chairs fill with grace.",
