        "bookId": "LUK",
        "bookName": "Luke",
        "chapterNumber": 18,
        "verseNumber": 4,
        "text": "He wouldn’t for a while, but afterward he said to himself, ‘Though I neither fear God, nor respect man,",
        "translation": "WEB",
        "illustrationId": "ill-luk-18",
        "linkedEntities": []
