        "bookId": "LUK",
        "bookName": "Luke",
        "chapterNumber": 24,
        "verseNumber": 16,
        "text": "But their eyes were kept from recognizing him.",
        "translation": "WEB",
        "illustrationId": "ill-luk-24",
